@"std/system"
relations: {dependsOn: $.std.Relation & {inverse: usedBy}}
a: id(a) & {dependsOn: [&: refer(), b]}
b: id(b) & {usedBy: [&: refer(), b]}

@"std/system"
relations: {dependsOn: $.std.Relation & {inverse: usedBy, acyclic: true}}
